import re

def run(spec: str, verilog: str, ports: list[dict]) -> dict:
    """
    Detect asynchronous reset usage (negedge resetn) in always blocks.
    Returns {'fired': True, 'findings': [msg]} if found.
    """
    # Look for always blocks with sensitivity list containing negedge resetn
    # Simple regex: always @\\(.*?negedge\\s+resetn.*?\\)
    pattern = r'always\\s*@\\s*\\([^)]*?negedge\\s+resetn[^)]*\\)'
    matches = re.findall(pattern, verilog, re.IGNORECASE | re.DOTALL)
    if matches:
        return {"fired": True, "findings": ["Design uses asynchronous reset (negedge resetn) in an always block; spec expects synchronous reset."]}
    return {"fired": False, "findings": []}
